        'class RunDistanceLimiter:\n'
        '    """Unsigned raw-wheel-speed odometry, trapezoidal integration on monotonic time.\n'
        '\n'
        '    Active only in policy state 3. Start resets the per-run budget; stopping\n'
        '    keeps the final estimate visible. Frequent supervisor/policy checks share\n'
        '    one integration clock, so a cached sample is never double-counted. Encoder\n'
        '    scale, slip, slew/coasting and sampling errors affect physical stop distance.\n'
        '    """\n'
        '    def __init__(self, maximum_m, max_gap_s):\n'
        '        self.maximum_m, self.max_gap_s = maximum_m, max_gap_s\n'
        '        self.reset()\n'
        '\n'
        '    def reset(self, now_s=None, speed_mps=None):\n'
        '        self.distance_m = 0.0\n'
        '        self.previous_time_s, self.previous_speed_mps = now_s, speed_mps\n'
        '\n'
        '    def advance(self, speed_mps, now_s):\n'
        '        if not all(finite_number(v) for v in (speed_mps, now_s)) or speed_mps < 0:\n'
        '            return "Invalid wheel-speed distance input"\n'
        '        if self.previous_time_s is not None:\n'
        '            dt = now_s-self.previous_time_s\n'
        '            if not 0 <= dt <= self.max_gap_s+1e-9:\n'
        '                return "Wheel-speed distance clock/gap invalid"\n'
        '            self.distance_m += 0.5*(self.previous_speed_mps+speed_mps)*dt\n'
