        '    """Derivative on measurement, filtered; conditional anti-windup."""\n'
        '    def __init__(self, kp, ki, kd, tau):\n'
        '        self.kp, self.ki, self.kd, self.tau = kp, ki, kd, tau\n'
        '        self.integral = self.derivative = 0.0\n'
        '        self.previous = None\n'
        '\n'
        '    def update(self, error, measurement, dt, low, high, feedforward=0.0):\n'
        '        increment = error*dt\n'
        '        if dt > 0 and self.previous is not None:\n'
        '            self.derivative += dt/(self.tau+dt)*((measurement-self.previous)/dt-self.derivative)\n'
        '        self.previous = measurement\n'
        '        base = feedforward+self.kp*error-self.kd*self.derivative\n'
        '        proposed = base+self.ki*(self.integral+increment)\n'
        '        if low <= proposed <= high or proposed > high and error < 0 or proposed < low and error > 0:\n'
        '            self.integral += increment\n'
        '        result = base+self.ki*self.integral\n'
        '        if not all(finite_number(v) for v in (result, self.integral, self.derivative)):\n'
        '            raise ValueError("nonfinite_control_state")\n'
        '        return max(low, min(high, result))\n'
        '\n'
        '\n'
        'def _control_poly_eval(coeffs, x):\n'
        '    result = 0.0\n'
        '    for coefficient in reversed(coeffs):\n'
        '        result = result*x+coefficient\n'
        '    return result\n'
        '\n'
        '\n'
        'def _control_poly_roots(coeffs):\n'
        '    """All real roots on [-1,1], using derivative isolation + bounded bisection.\n'
        '\n'
        '    The caller supplies degree <= 9. Each derivative has smaller degree; there\n'
        '    are at most degree monotone intervals and 60 bisections per interval. Handles\n'
        '    repeated roots at derivative roots. No NumPy or external offline imports.\n'
        '    """\n'
        '    coeffs = list(coeffs)\n'
        '    while len(coeffs) > 1 and coeffs[-1] == 0:\n'
        '        coeffs.pop()\n'
        '    size = max(abs(v) for v in coeffs)\n'
        '    if not finite_number(size):\n'
        '        raise ValueError("nonfinite_path_geometry")\n'
        '    if size == 0 or len(coeffs) == 1:\n'
        '        return []\n'
        '    coeffs = [v/size for v in coeffs]\n'
        '    if len(coeffs) == 2:\n'
        '        root = -coeffs[0]/coeffs[1]\n'
        '        return [root] if -1 <= root <= 1 else []\n'
        '    critical = _control_poly_roots([i*v for i, v in enumerate(coeffs) if i])\n'
        '    knots = sorted(set([-1.0, *critical, 1.0]))\n'
        '    roots = [x for x in knots if abs(_control_poly_eval(coeffs, x)) <= 1e-12]\n'
        '    for low, high in zip(knots, knots[1:]):\n'
        '        f_low, f_high = _control_poly_eval(coeffs, low), _control_poly_eval(coeffs, high)\n'
        '        if (f_low > 0) == (f_high > 0) or f_low == 0 or f_high == 0:\n'
        '            continue\n'
        '        for _ in range(60):\n'
        '            mid = low/2+high/2\n'
        '            f_mid = _control_poly_eval(coeffs, mid)\n'
        '            if f_mid == 0:\n'
        '                low = high = mid\n'
        '                break\n'
        '            if (f_low > 0) == (f_mid > 0):\n'
        '                low, f_low = mid, f_mid\n'
        '            else:\n'
        '                high = mid\n'
        '        roots.append(low/2+high/2)\n'
        '    return sorted(set(roots))\n'
        '\n'
        '\n'
        'def _control_centerline_geometry(path):\n'
        '    """Nearest segment cross-track error plus a forward tangent for steering.\n'
        '\n'
        '    O(N), N <= 201. Use observed points only, with no polynomial fit, extension\n'
        '    or recovery path. Endpoint tangents approximate error for front-only input.\n'
        '    """\n'
        '    points = CenterlinePlanner._points(path.get("samples_xy"))\n'
        '    preview = path.get("preview_m")\n'
        '    bounds = path.get("range")\n'
        '    if (points is None or path.get("independent_variable") != "x_m"\n'
        '            or not isinstance(bounds, (list, tuple)) or len(bounds) != 2\n'
        '            or not all(finite_number(v) for v in bounds)\n'
        '            or list(bounds) != [points[0][0], points[-1][0]] or points[-1][0] <= 0\n'
        '            or not finite_number(preview) or preview <= 0):\n'
        '        raise ValueError("invalid_centerline_path")\n'
        '    nearest = None\n'
        '    for i, (a, b) in enumerate(zip(points, points[1:])):\n'
        '        dx, dy = b[0]-a[0], b[1]-a[1]\n'
        '        u = max(0.0, min(1.0, -(a[0]*dx+a[1]*dy)/(dx*dx+dy*dy)))\n'
        '        x, y = a[0]+u*dx, a[1]+u*dy\n'
        '        cost = x*x+y*y\n'
        '        if nearest is None or cost < nearest[0]:\n'
        '            nearest = (cost, x, y, math.atan2(dy, dx), i, u)\n'
        '    _, x, y, tangent, index, u = nearest\n'
        '    target_x = max(points[0][0], min(points[-1][0], max(0.0, x)+preview))\n'
        '    segment = len(points)-2\n'
        '    for i, (_, b) in enumerate(zip(points, points[1:])):\n'
        '        if target_x <= b[0]:\n'
        '            segment = i\n'
        '            break\n'
        '    a, b = points[segment], points[segment+1]\n'
        '    slope = (b[1]-a[1])/(b[0]-a[0])\n'
        '    target_y = a[1]+slope*(target_x-a[0])\n'
        '    # Curvature is diagnostic only in MVP. Use three neighboring observed points.\n'
        '    j = max(1, min(len(points)-2, segment+1))\n'
        '    curvature = 0.0\n'
        '    if len(points) >= 3:\n'
        '        a0, b0, c0 = points[j-1:j+2]\n'
        '        ab, bc, ac = (b0[0]-a0[0], b0[1]-a0[1]), (c0[0]-b0[0], c0[1]-b0[1]), (c0[0]-a0[0], c0[1]-a0[1])\n'
        '        curvature = 2*(ab[0]*bc[1]-ab[1]*bc[0])/(math.hypot(*ab)*math.hypot(*bc)*math.hypot(*ac))\n'
        '    result = {"path_error_m": -x*math.sin(tangent)+y*math.cos(tangent),\n'
        '              "path_heading_rad": math.atan(slope), "curvature_1pm": curvature,\n'
        '              "closest_x_m": x, "closest_y_m": y, "preview_x_m": target_x, "preview_y_m": target_y,\n'
        '              "closest_at_range_end": index == 0 and u == 0 or index == len(points)-2 and u == 1,\n'
        '              "path_encoding": "CARTESIAN_CENTERLINE"}\n'
        '    if not all(finite_number(v) for k, v in result.items() if k not in ("path_encoding", "closest_at_range_end")):\n'
        '        raise ValueError("nonfinite_centerline_geometry")\n'
        '    return result\n'
        '\n'
        '\n'
        'def _control_ordered_geometry(path):\n'
        '    points = _path_points(path.get("samples_xy"))\n'
        '    preview = path.get("preview_m")\n'
        '    if points is None or path.get("independent_variable") != "s_m" or not finite_number(preview) or preview <= 0:\n'
        '        raise ValueError("invalid_ordered_path")\n'
        '    lengths = _path_lengths(points)\n'
        '    bounds = path.get("range")\n'
        '    if (not isinstance(bounds, (tuple, list)) or len(bounds) != 2\n'
        '            or not all(finite_number(v) for v in bounds)\n'
        '            or bounds[0] != 0 or abs(bounds[1]-lengths[-1]) > 1e-6):\n'
        '        raise ValueError("invalid_ordered_path_range")\n'
        '    nearest = _path_project(points, lengths)\n'
        '    if nearest is None:\n'
        '        raise ValueError("ordered_branch_unavailable")\n'
        '    _, distance, (x, y), index, u = nearest\n'
        '    target_s = min(lengths[-1], distance+preview)\n'
        '    target = _path_sample(points, lengths, target_s)\n'
        '    tx, ty = _path_tangent(points, lengths, distance)\n'
        '    hx, hy = _path_tangent(points, lengths, target_s)\n'
        '    # Signed local-normal error and an arc-length preview tangent still drive\n'
        '    # the existing PI + heading P. No pure-pursuit curvature law is used.\n'
        '    before = max(0.0, target_s-0.15)\n'
        '    after = min(lengths[-1], target_s+0.15)\n'
        '    a = _path_tangent(points, lengths, before)\n'
        '    b = _path_tangent(points, lengths, after)\n'
        '    curvature = wrap_angle(math.atan2(b[1], b[0])-math.atan2(a[1], a[0]))/(after-before)\n'
        '    return {"path_error_m": -x*ty+y*tx, "path_heading_rad": math.atan2(hy, hx),\n'
        '            "curvature_1pm": curvature, "closest_x_m": x, "closest_y_m": y,\n'
        '            "closest_s_m": distance, "preview_s_m": target_s,\n'
        '            "preview_x_m": target[0], "preview_y_m": target[1],\n'
        '            # Zero on an interior projection; continuous as the observed\n'
        "            # first segment reaches/passes the vehicle's normal projection.\n"
        '            "unobserved_entry_distance_m": max(0.0, x*tx+y*ty) if index == 0 and u == 0 else 0.0,\n'
        '            "closest_at_range_end": index == 0 and u == 0 or index == len(points)-2 and u == 1,\n'
        '            "forward_target_only": index == 0 and u == 0 and x*tx+y*ty > 1e-6,\n'
        '            "path_encoding": "ORDERED_CENTERLINE"}\n'
        '\n'
        '\n'
        'def control_path_geometry(path):\n'
        '    """Bounded closest observed point for y(x), up to fifth degree.\n'
        '\n'
        '    u=(x-origin)/scale, low-to-high coefficients, physical range in metres.\n'
        '    Front-only support is retained; endpoint tangent error is an approximation,\n'
        '    not evidence of observed road at the car origin. No path extrapolation.\n'
        '    """\n'
        '    if isinstance(path, dict) and path.get("type") == "CARTESIAN_CENTERLINE":\n'
        '        return _control_centerline_geometry(path)\n'
        '    if isinstance(path, dict) and path.get("type") == "ORDERED_CENTERLINE":\n'
        '        return _control_ordered_geometry(path)\n'
        '    if (not isinstance(path, dict) or path.get("type") != "CARTESIAN_Y_OF_X"\n'
        '            or path.get("independent_variable") != "x_m"):\n'
        '        raise ValueError("unsupported_path_encoding")\n'
        '    coeffs, bounds = path.get("coeffs_low_to_high"), path.get("range")\n'
        '    origin, scale = path.get("origin"), path.get("scale")\n'
        '    if (not isinstance(coeffs, (list, tuple)) or not 1 <= len(coeffs) <= 6\n'
        '            or not all(finite_number(v) for v in coeffs)):\n'
        '        raise ValueError("invalid_polynomial")\n'
        '    if (not isinstance(bounds, (list, tuple)) or len(bounds) != 2\n'
        '            or not all(finite_number(v) for v in bounds)\n'
        '            or not bounds[0] < bounds[1] or bounds[1] <= 0\n'
        '            or not finite_number(origin) or not finite_number(scale) or scale <= 0):\n'
        '        raise ValueError("invalid_path_range_or_normalization")\n'
        '    mid, half = bounds[0]/2+bounds[1]/2, bounds[1]/2-bounds[0]/2\n'
        '    offset, factor = (mid-origin)/scale, half/scale\n'
        '    # Compose y(mid+half*t), t in [-1,1], with <= 6 coefficients.\n'
        '    y = [0.0]*len(coeffs)\n'
        '    for i, coefficient in enumerate(coeffs):\n'
        '        for j in range(i+1):\n'
        '            y[j] += coefficient*math.comb(i, j)*offset**(i-j)*factor**j\n'
        '    dy = [i*v for i, v in enumerate(y) if i] or [0.0]\n'
        '    stationary = [mid*half, half*half]+[0.0]*max(0, 2*len(y)-4)\n'
        '    for i, a in enumerate(y):\n'
        '        for j, b in enumerate(dy):\n'
        '            stationary[i+j] += a*b\n'
        '    candidates = [-1.0, 1.0, *_control_poly_roots(stationary)]\n'
        '    costs = [(mid+half*t)**2+_control_poly_eval(y, t)**2 for t in candidates]\n'
        '    if not all(finite_number(v) for v in costs):\n'
        '        raise ValueError("nonfinite_path_geometry")\n'
        '    t = candidates[min(range(len(costs)), key=costs.__getitem__)]\n'
        '    x, value = mid+half*t, _control_poly_eval(y, t)\n'
        '    slope = _control_poly_eval(dy, t)/half\n'
        '    ddy = [i*v for i, v in enumerate(dy) if i] or [0.0]\n'
        '    second = _control_poly_eval(ddy, t)/half**2\n'
        '    heading = math.atan(slope)\n'
        '    geometry = {"path_error_m": -x*math.sin(heading)+value*math.cos(heading),\n'
        '                "path_heading_rad": heading, "curvature_1pm": second/math.hypot(1, slope)**3,\n'
        '                "closest_x_m": x, "closest_y_m": value, "path_degree": len(coeffs)-1,\n'
        '                "closest_at_range_end": t in (-1.0, 1.0)}\n'
        '    if not all(finite_number(v) for k, v in geometry.items() if k != "closest_at_range_end"):\n'
        '        raise ValueError("nonfinite_path_geometry")\n'
        '    return geometry\n'
        '\n'
        '\n'
        'class ControlReferenceManager:\n'
        '    """MVP straight-reference cache; never edits the upstream planning output.\n'
        '\n'
        '    Cache budgets start at acceptance of a DISTINCT observed cone frame. Motion\n'
        '    is integrated incrementally, preserving the original source timestamp. The\n'
        '    manager generates geometry, never cached actuator commands. Prediction may\n'
        '    end earlier than its budgets when observed support or motion history ends.\n'
        '    """\n'
        '    SOFT_REASONS = frozenset({\n'
        '        "invalid_estimates", "stale_road", "v1_requires_both_boundaries",\n'
        '        "unsupported_road_curvature", "insufficient_near_or_far_coverage",\n'
        '        "not_straight_enough", "outside_v1_offset_or_heading_domain"})\n'
        '\n'
        '    def __init__(self, settings):\n'
        '        self.settings = settings\n'
        '        self.clear()\n'
        '\n'
        '    def clear(self):\n'
        '        self.reference = None\n'
        '        self.source_stamp_s = self.accepted_at_s = self.accepted_distance_m = None\n'
        '        self.frame_time_s = None\n'
        '        self.endpoints = None\n'
        '        self.mode = "TRACKING"\n'
        '        self.diagnostics = {}\n'
        '\n'
        '    def problem(self, monotonic_s, distance_m):\n'
        '        if self.reference is None:\n'
        '            return "No trusted control reference"\n'
        '        elapsed, distance = monotonic_s-self.accepted_at_s, distance_m-self.accepted_distance_m\n'
        '        if not all(finite_number(v) and v >= 0 for v in (elapsed, distance)):\n'
        '            return "Control cache clock/distance invalid"\n'
        '        if elapsed+1e-9 >= self.settings.reference_hold_max_s:\n'
        '            return "Control reference hold time exhausted"\n'
        '        if distance+1e-9 >= self.settings.reference_hold_max_distance_m:\n'
        '            return "Control reference hold distance exhausted"\n'
        '        return None\n'
        '\n'
        '    def select(self, reference, road, state, motion, now_s, monotonic_s, distance_m, execution_lifetime_s):\n'
        '        if (state.get("valid") is not True or not finite_number(execution_lifetime_s)\n'
        '                or execution_lifetime_s <= 0):\n'
        '            raise ValueError("Control recovery motion feedback unavailable")\n'
        '        source_stamp = road.get("measurement_timestamp_s")\n'
        '        usable = reference.get("valid") is True\n'
        '        if usable:\n'
        '            stamp, lifetime = reference.get("timestamp_s"), reference.get("valid_for_s")\n'
        '            if not all(finite_number(v) for v in (stamp, lifetime)) or lifetime <= 0 or stamp > now_s:\n'
        '                raise ValueError("Invalid upstream control reference timestamp")\n'
        '            if (reference.get("frame_id") != state.get("frame_id")\n'
        '                    or reference.get("vehicle_reference_point") != "cg_ground_projection"\n'
        '                    or abs(stamp-state.get("timestamp_s", math.inf)) > 1e-6):\n'
        '                raise ValueError("control_frame_or_time_mismatch")\n'
        '            if reference.get("stop_requested") or reference.get("target_speed_mps") == 0:\n'
        '                return reference\n'
        '            usable = now_s < stamp+lifetime\n'
        '        reason = reference.get("reason") if not reference.get("valid") else "reference_expired"\n'
        '        if not usable and reason not in self.SOFT_REASONS | {"reference_expired"}:\n'
        '            raise ValueError("Planning: " + str(reason))\n'
        '\n'
        '        path = reference.get("path") if usable else None\n'
        '        straight = (isinstance(path, dict) and path.get("type") == "CARTESIAN_Y_OF_X"\n'
        '                    and path.get("independent_variable") == "x_m"\n'
        '                    and isinstance(path.get("coeffs_low_to_high"), (list, tuple))\n'
        '                    and 1 <= len(path["coeffs_low_to_high"]) <= 2)\n'
        '        if usable and not straight:\n'
        '            # Other path encodings keep their original control/deadline behavior.\n'
        '            self.clear()\n'
        '            return reference\n'
        '        if usable:\n'
        '            control_path_geometry(path)  # Validate the full polynomial contract.\n'
        '            if not finite_number(source_stamp) or source_stamp > now_s:\n'
        '                raise ValueError("Invalid trusted road timestamp")\n'
        '            if self.source_stamp_s is not None and source_stamp < self.source_stamp_s:\n'
        '                raise ValueError("Control road sample moved backwards")\n'
        '            if self.reference is None or source_stamp != self.source_stamp_s:\n'
        '                self.reference = deepcopy(reference)\n'
        '                self.source_stamp_s = source_stamp\n'
        '                self.accepted_at_s, self.accepted_distance_m = monotonic_s, distance_m\n'
        '                self.frame_time_s = stamp\n'
        '                coeffs = path["coeffs_low_to_high"]\n'
        '                self.endpoints = [(x, _control_poly_eval(coeffs, (x-path["origin"])/path["scale"]))\n'
        '                                  for x in path["range"]]\n'
        '\n'
        '        if not usable:\n'
        '            problem = self.problem(monotonic_s, distance_m)\n'
        '            if problem:\n'
        '                raise ValueError(problem)\n'
        '        if self.reference is not None:\n'
        '            pose, problem = motion.pose_between(self.frame_time_s, now_s)\n'
        '            if problem:\n'
        '                raise ValueError("Control cache motion: " + problem)\n'
        '            endpoints = [motion.transform_xy(p, pose) for p in self.endpoints]\n'
        '            (x0, y0), (x1, y1) = endpoints\n'
        '            if (not all(finite_number(v) for point in endpoints for v in point)\n'
        '                    or x1 <= max(0.0, x0)):\n'
        '                raise ValueError("Control cached path support exhausted")\n'
        '            slope = (y1-y0)/(x1-x0)\n'
        '            intercept = y0-slope*x0\n'
        '            self.endpoints, self.frame_time_s = endpoints, now_s\n'
        '            predicted_path = {"type": "CARTESIAN_Y_OF_X", "independent_variable": "x_m",\n'
        '                              "origin": 0.0, "scale": 1.0,\n'
        '                              "coeffs_low_to_high": [intercept, slope],\n'
        '                              "range": [max(0.0, x0), x1]}\n'
        '\n'
        '        selected = deepcopy(reference if usable else self.reference)\n'
        '        if not usable:\n'
        '            selected["path"] = predicted_path\n'
        '        selected.update(timestamp_s=now_s, valid_for_s=execution_lifetime_s)\n'
        '        self.mode = "TRACKING" if usable else "DEGRADED"\n'
        '        self.diagnostics = {\n'
        '            "tracking_mode": self.mode, "upstream_rejection_reason": None if usable else reason,\n'
        '            "original_measurement_timestamp_s": self.source_stamp_s,\n'
        '            "original_source_age_s": now_s-self.source_stamp_s,\n'
        '            "cache_age_s": monotonic_s-self.accepted_at_s,\n'
        '            "prediction_distance_m": distance_m-self.accepted_distance_m,\n'
        '            "remaining_path_range_m": list(selected["path"]["range"])}\n'
        '        return selected\n'
        '\n'
        '\n'
        'class PolicyController:\n'
        '    """Single-file forward-only control; failures request the framework stop.\n'
        '\n'
        '    Does not implement ESC negative-drive brake/hold, physical enabling, frame\n'
        '    propagation or automatic resume. All those concerns stay explicit.\n'
        '    """\n'
        '    def __init__(self, settings, frame_id="base_link"):\n'
        '        self.settings, self.frame_id = settings, frame_id\n'
        '        self.clear()\n'
        '\n'
        '    def clear(self):\n'
        '        cfg = self.settings\n'
        '        self.speed = ControlPID(cfg.speed_kp, cfg.speed_ki, cfg.speed_kd, cfg.derivative_tau_s)\n'
        '        self.lateral = ControlPID(cfg.lateral_kp, cfg.lateral_ki, cfg.lateral_kd, cfg.derivative_tau_s)\n'
        '        self.mvp_lateral = ControlPID(cfg.mvp_lateral_kp, cfg.mvp_lateral_ki, 0.0, cfg.derivative_tau_s)\n'
        '        self._mvp_previous_steer = 0.0\n'
        '        self._mvp_filtered_errors = None\n'
        '\n'
        '    def calculate(self, reference, state, vehicle_params, now_s, dt):\n'
        '        try:\n'
        '            if (not isinstance(reference, dict) or reference.get("valid") is not True\n'
        '                    or not isinstance(state, dict) or state.get("speed_valid") is not True):\n'
        '                raise ValueError("invalid_planning_or_speed")\n'
        '            stamp, lifetime = reference.get("timestamp_s"), reference.get("valid_for_s")\n'
        '            if (not all(finite_number(v) for v in (stamp, lifetime, now_s, dt))\n'
        '                    or lifetime <= 0 or not 0 <= dt <= self.settings.max_dt_s\n'
        '                    or not stamp <= now_s < stamp+lifetime):\n'
        '                raise ValueError("reference_expired_or_control_gap")\n'
        '            if (reference.get("frame_id") != self.frame_id or state.get("frame_id") != self.frame_id\n'
        '                    or reference.get("vehicle_reference_point") != "cg_ground_projection"\n'
        '                    or not finite_number(state.get("timestamp_s"))\n'
        '                    or abs(state["timestamp_s"]-stamp) > 1e-6):\n'
        '                raise ValueError("control_frame_or_time_mismatch")\n'
        '            # now_s may be slightly later due to computation, but state and path\n'
        '            # must come from the SAME cycle. This caller never replays a reference.\n'
        '            target, speed = reference.get("target_speed_mps"), state.get("speed_mps")\n'
        '            if not all(finite_number(v) and v >= 0 for v in (target, speed)):\n'
        '                raise ValueError("invalid_speed")\n'
        '            stop = reference.get("stop_requested")\n'
        '            if not isinstance(stop, bool):\n'
        '                raise ValueError("invalid_stop_request")\n'
        '            if stop or target == 0:\n'
        '                self.clear()\n'
