        '                    raise ValueError("simulation_control_requires_simulation_reference")\n'
        '                params = {"valid": True, "source": "course_simulation",\n'
        '                          "vehicle_reference_point": "cg_ground_projection",\n'
        '                          "effective_wheelbase_m": 0.33, "rear_axle_from_cg_m": 0.132,\n'
        '                          "steering_limit_rad": math.pi/4, "steering_direction": 1.0}\n'
        '            elif reference.get("simulation_only"):\n'
        '                raise ValueError("simulation_reference_rejected_for_live_control")\n'
        '            if (not simulated and isinstance(params, dict) and\n'
        '                    (params.get("simulation_only") or params.get("source") in\n'
        '                     ("course_simulation", "offline_test_assumption"))):\n'
        '                raise ValueError("simulation_geometry_rejected_for_live_control")\n'
        '            if (not isinstance(params, dict) or params.get("valid") is not True\n'
