        '                boundaries = [road.get(f"{side}_boundary_xy") for side in ("left", "right")]\n'
        '                if (any(not points or any(b[0] <= a[0] for a, b in zip(points, points[1:]))\n'
        '                        for points in boundaries)):\n'
        '                    problem = "near_field_requires_both_boundaries"\n'
        '                else:\n'
        '                    lo = max(center[0][0], *(points[0][0] for points in boundaries))\n'
        '                    hi = min(center[-1][0], *(points[-1][0] for points in boundaries))\n'
        '                    oldest = road.get("oldest_observation_timestamp_s", source_time)\n'
        '                    road["near_field"].update(coverage_x_m=[lo, hi],\n'
        '                                              oldest_observation_age_s=max(0.0, now_s-oldest))\n'
        '                    if lo > 1e-9 or hi < 0:\n'
        '                        problem = "near_field_unobserved"\n'
        '                    elif now_s-oldest > self.settings.history_lifetime_s:\n'
        '                        problem = "near_field_history_expired"\n'
        '                    else:\n'
        '                        road["near_field"].update(valid=True, status="observed_support")\n'
        '        if problem is not None:\n'
        '            if (road["geometry_valid"] and (problem == "near_field_unobserved"\n'
        '                    or (problem == "near_field_requires_both_boundaries"\n'
        '                        and road.get("single_side_inferred_from_learned_width")))):\n'
        '                # Retain validated, aligned FORWARD observations separately.\n'
        '                # Estimator validity stays false; only an explicitly configured\n'
        '                # planning extension may consume this incomplete support.\n'
        '                forward = deepcopy(road)\n'
        '                forward.update(valid=False, status=problem)\n'
        '                road["forward_geometry"] = forward\n'
        '            road["near_field"]["status"] = problem\n'
        '            road.update(valid=False, status=problem, timestamp_s=None,\n'
        '                        time_aligned=False, motion_compensated=False,\n'
        '                        centerline_xy=[], left_boundary_xy=None, right_boundary_xy=None,\n'
        '                        lane_width_m=None, x_range_m=None, local_curvature_1pm=None,\n'
        '                        confidence=0.0, motion_compensation=None)\n'
