        '\n'
        '    def _align_observed_boundary(self, road, source_time, now_s, state_valid):\n'
        '        """Expose an aligned measured side without admitting a full corridor.\n'
        '\n'
        '        Native planning can use one observed side. Baseline corridor validity,\n'
        '        learned width and trusted-road prediction remain unchanged.\n'
        '        """\n'
        '        boundaries = {side: road.get(side+"_boundary_xy") for side in ("left", "right")}\n'
        '        road.update(left_boundary_xy=None, right_boundary_xy=None)\n'
        '        pose, problem = self.motion.pose_between(source_time, now_s)\n'
        '        if not state_valid:\n'
        '            problem = "motion_state_unavailable"\n'
        '        aligned = {}\n'
        '        if problem is None:\n'
        '            for side, points in boundaries.items():\n'
        '                if not points:\n'
        '                    continue\n'
        '                transformed = [self.motion.transform_xy(p, pose) for p in points]\n'
        '                if (_path_points(transformed) is None\n'
        '                        or _path_lengths(transformed)[-1] < self.settings.road_min_coverage_m):\n'
        '                    problem = "motion_transformed_geometry_invalid"\n'
        '                    break\n'
        '                aligned[side] = transformed\n'
        '        if problem is None and aligned:\n'
        '            forward = deepcopy(road)\n'
        '            forward.update(timestamp_s=now_s, time_aligned=True, geometry_valid=True,\n'
        '                           motion_compensated=pose["interval_s"] > 0, motion_compensation=pose)\n'
        '            for side, points in aligned.items():\n'
        '                forward[side+"_boundary_xy"] = points\n'
        '            road["forward_geometry"] = forward\n'
        '        road["near_field"]["status"] = problem or road["status"]\n'
        '        return road\n'
        '\n'
        '    def _align_ordered_road(self, road, source_time, now_s, state_valid):\n'
        '        pose, problem = self.motion.pose_between(source_time, now_s)\n'
        '        if not state_valid:\n'
        '            problem = "motion_state_unavailable"\n'
        '        if problem is None:\n'
        '            center = [self.motion.transform_xy(p, pose) for p in road["centerline_xy"]]\n'
        '            points = _path_points(center)\n'
        '            if points is None:\n'
        '                problem = "motion_transformed_geometry_invalid"\n'
        '            else:\n'
        '                lengths = _path_lengths(points)\n'
        '                projection = _path_project(points, lengths)\n'
        '                if projection is None:\n'
        '                    problem = "ordered_branch_unavailable"\n'
        '                else:\n'
        '                    # Keep one contiguous local arc around this branch. Body\n'
        '                    # x may turn back; clipping/sorting by x would break U turns.\n'
        '                    near_s = projection[1]\n'
        '                    lo = max(0.0, near_s-self.settings.road_rear_support_m)\n'
        '                    hi = min(lengths[-1], near_s+self.settings.road_forward_max_m)\n'
        '                    center = [_path_sample(points, lengths, lo)]\n'
        '                    center.extend(p for p, s in zip(points, lengths) if lo+1e-6 < s < hi-1e-6)\n'
        '                    center.append(_path_sample(points, lengths, hi))\n'
        '                    if hi-lo < self.settings.road_min_coverage_m or _path_points(center) is None:\n'
        '                        problem = "motion_transformed_geometry_invalid"\n'
        '                    else:\n'
        '                        road.update(centerline_xy=center, arc_length_m=_path_lengths(center)[-1],\n'
        '                                    x_range_m=[min(p[0] for p in center), max(p[0] for p in center)],\n'
        '                                    timestamp_s=now_s, time_aligned=True, geometry_valid=True,\n'
        '                                    motion_compensated=pose["interval_s"] > 0, motion_compensation=pose)\n'
        '                        for side in ("left", "right"):\n'
        '                            key = side+"_boundary_xy"\n'
        '                            if road[key] is not None:\n'
        '                                road[key] = [self.motion.transform_xy(p, pose) for p in road[key]]\n'
        '                        road["near_field"].update(coverage_s_m=[lo-near_s, hi-near_s],\n'
        '                            oldest_observation_age_s=now_s-road.get("oldest_observation_timestamp_s", source_time))\n'
        '                        if road.get("single_side_inferred_from_learned_width"):\n'
        '                            problem = "near_field_requires_both_boundaries"\n'
        '                        elif near_s <= 1e-6 or near_s >= lengths[-1]-1e-6:\n'
        '                            problem = "near_field_unobserved"\n'
        '                        elif road["near_field"]["oldest_observation_age_s"] > self.settings.history_lifetime_s:\n'
        '                            problem = "near_field_history_expired"\n'
        '                        else:\n'
        '                            road["near_field"].update(valid=True, status="observed_support")\n'
        '        if problem is not None:\n'
        '            if road["geometry_valid"] and problem in ("near_field_unobserved", "near_field_requires_both_boundaries"):\n'
        '                forward = deepcopy(road)\n'
        '                forward.update(valid=False, status=problem)\n'
        '                road["forward_geometry"] = forward\n'
        '            road["near_field"]["status"] = problem\n'
        '            road.update(valid=False, status=problem, timestamp_s=None, time_aligned=False,\n'
        '                        centerline_xy=[], left_boundary_xy=None, right_boundary_xy=None,\n'
        '                        lane_width_m=None, x_range_m=None, arc_length_m=None, confidence=0.0)\n'
        '        return road\n'
        '\n'
        '    def update(self, observations, ages, stamps, sample_receipts, now_s,\n'
        '               sample_receipt_ros_ns=None):\n'
        '        clock_valid = self.motion.check_clock(now_s)\n'
        '        receipt_stamps = sample_receipt_ros_ns or {}\n'
        '        for name, component in (("wheel_speed", None), ("imu_angular_velocity", 2)):\n'
        '            value = observations.get(name)\n'
        '            if not clock_valid or not self._fresh(value, ages.get(name)):\n'
