        '\n'
        '        speed = self.motion.current("wheel_speed", now_s) if clock_valid else None\n'
        '        yaw_rate = self.motion.current("imu_angular_velocity", now_s) if clock_valid else None\n'
        '        state = {"timestamp_s": now_s, "frame_id": self.frame_id,\n'
