        '            # Keep measured near support for a NEW camera frame, but this old\n'
        '            # camera epoch cannot re-arm an expired prediction on its own.\n'
        '            self._trusted_road, self._failure_since_s = None, None\n'
        '            self._prediction_motion_stamp = None\n'
        '        elif continuous and road["status"] in self.CAMERA_GAP_FAILURES:\n'
