        '                fusion.setdefault("reason", "no_feasible_fused_candidate")\n'
        '                if result:\n'
        '                    fusion["failed_fused_attempt"] = {"reference": road.get("centerline_xy"),\n'
        '                        "candidate_count": result.get("candidate_count"), "feasible_count": result.get("feasible_count"),\n'
        '                        "selected": result.get("selected"), "elapsed_s": result.get("elapsed_s")}\n'
        '                result = None\n'
        '        if result is None:\n'
        '            result = self._plan_geometry(job)\n'
        '            fusion.pop("guide", None)\n'
        '            fusion.update(raw_fallback_used=True, selected_source="raw", raw_status=result["status"])\n'
        '        else:\n'
        '            fusion.update(raw_fallback_used=False, selected_source="fused", raw_status=None)\n'
        '        fusion.setdefault("reason", "temporal_reference")\n'
        '        fusion["collection"] = collection\n'
        '        fusion["degraded"] = fusion.get("status") != "FUSED" or bool(collection.get("events"))\n'
        '        result["fusion"] = fusion\n'
        '        result["temporal_input"] = {key: job.get(key) for key in\n'
        '            ("road_history", "shadow_pose", "shadow_odometry_epoch", "previous_reference", "temporal_collection")}\n'
        '        result["raw_planning_input"] = {"road": job.get("road"), "state": job.get("state")}\n'
        '        if fusion.get("status") == "FUSED":\n'
        '            result["reference_support_kind"] = "fused_guidance_not_observed_boundary"\n'
        '            result["reference_observed_range_s_m"] = None\n'
        '            result["observed_centerline_length_m"] = _shadow_lengths(_shadow_points(\n'
