        '        amplitude = (width or 2*cfg.search_half_width_m)*cfg.preparation_width_fraction\n'
        '        preparation = -amplitude*max(-1.0, min(1.0, turn/(math.pi/2)))\n'
        '        search = max(cfg.search_half_width_m, abs(d0))\n'
