        '\n'
        'class FirstOrderSampleFilter:\n'
        '    """Causal low-pass; a cached sample is assimilated exactly once.\n'
        '\n'
        '    sample_key identifies an accepted source message, not its numerical value.\n'
        '    sample_time_s is ROS sample time for gyro, monotonic receipt for wheel speed;\n'
        '    each filter stays in its own time domain. Source freshness is checked by the\n'
        '    caller. New runs and discontinuities reset rather than bridge stale history.\n'
        '    """\n'
        '    def __init__(self, tau_s, reset_gap_s):\n'
        '        self.tau_s = tau_s\n'
        '        self.reset_gap_s = reset_gap_s\n'
        '        self.clear()\n'
        '\n'
        '    def clear(self):\n'
        '        self.value = self.sample_key = self.sample_time_s = None\n'
        '\n'
        '    def update(self, value, sample_key, sample_time_s):\n'
        '        if not finite_number(value) or sample_key is None or not finite_number(sample_time_s):\n'
        '            self.clear()\n'
        '            return None\n'
        '        if sample_key == self.sample_key:\n'
        '            return self.value\n'
        '        elapsed = None if self.sample_time_s is None else sample_time_s - self.sample_time_s\n'
        '        if self.value is None or elapsed is None or elapsed <= 0 or elapsed >= self.reset_gap_s:\n'
        '            self.value = float(value)\n'
        '        else:\n'
        '            alpha = -math.expm1(-elapsed / self.tau_s)\n'
        '            self.value += alpha * (value - self.value)\n'
        '        self.sample_key, self.sample_time_s = sample_key, sample_time_s\n'
        '        return self.value\n'
