        '                prefix = [p for p, s in zip(path, arc) if s <= end]\n'
        '                if end > 0:\n'
        '                    p = _shadow_at([p[:2] for p in path], arc, end)\n'
        '                    prefix.append((*p, prefix[-1][2]))\n'
        '            self._shadow_publish_path(self.shadow_path_publisher, path, stamp)\n'
        '            self._shadow_publish_path(self.shadow_prefix_publisher, prefix, stamp)\n'
        '            self._shadow_publish_path(self.shadow_reference_publisher, result.get("reference", []), stamp)\n'
        '            wire = result.get("wire_json") or json.dumps(result)\n'
        '            # The large candidate JSON was encoded off the executor. Append only\n'
