        '            summary = {key: result.get(key) for key in ("status", "job_id", "candidate_count", "feasible_count",\n'
        '                "speed_mps", "hold_time_s", "check_length_m", "score_length_m", "elapsed_s", "late_for_requested_period", "timing_s")}\n'
        '            summary.update(selected_id=selected.get("id") if selected else None,\n'
        '                selected_family=selected.get("family") if selected else None,\n'
        '                result_age_s=self.get_clock().now().nanoseconds/1e9-stamp,\n'
