        '        except Exception as error:\n'
        '            self._warn("shadow_publish", f"Shadow diagnostics unavailable: {error}")\n'
        '\n'
        '    def _publish_trajectory(self, ros_now_ns, force=False):\n'
        '        """Display the accepted reference at 10 Hz; existing stops clear it."""\n'
        '        if not self.trajectory_enabled:\n'
        '            return\n'
        '        now = self._monotonic()\n'
        '        if not force and now-self._trajectory_last_publish_s < 0.1:\n'
