        '                    points = path["samples_xy"]\n'
        '                else:\n'
        '                    cached = ref.get("control_cached_path_samples")\n'
        '                    lo, hi = (cached[0][0], cached[-1][0]) if cached else path["range"]\n'
        '                    points = []\n'
        '                    for i in range(81):\n'
        '                        x = lo if i == 0 else hi if i == 80 else lo+(hi-lo)*i/80\n'
        '                        sample = evaluate_planning_path(ref, x, ros_now_ns/1e9)\n'
        '                        if sample is None:\n'
        '                            points = []\n'
        '                            break\n'
        '                        points.append(sample["position_xy_m"])\n'
        '                if (2 <= len(points) <= 201\n'
        '                        and all(len(p) == 2 and all(finite_number(v) for v in p) for p in points)):\n'
        '                    message.header.stamp = Time(nanoseconds=round(ref["timestamp_s"]*1e9)).to_msg()\n'
        '                    for x, y in points:\n'
        '                        pose = PoseStamped(header=message.header)\n'
        '                        pose.pose.position.x, pose.pose.position.y = float(x), float(y)\n'
        '                        pose.pose.orientation.w = 1.0\n'
        '                        message.poses.append(pose)\n'
        '        except Exception as error:\n'
        '            message.poses = []\n'
        '            self._warn("trajectory_display", f"Trajectory display unavailable: {error}")\n'
        '        try:\n'
        '            self.trajectory_publisher.publish(message)\n'
        '            self._trajectory_last_publish_s = now\n'
        '        except Exception as error:\n'
        '            self._warn("trajectory_display", f"Trajectory display publication unavailable: {error}")\n'
        '\n'
        '    def _control_problem(self, monotonic_now, ros_now_ns):\n'
        '        """Distance/time budgets and reference expiry need no sensor callback."""\n'
        '        if not self.control_settings.enabled:\n'
        '            return None\n'
        '        wheel = self.observations.get("wheel_speed")\n'
        '        if wheel is None or not self._fresh("wheel_speed", monotonic_now, ros_now_ns):\n'
        '            return "Wheel speed unavailable for distance limit"\n'
        '        problem = self.distance_limiter.advance(wheel.value, monotonic_now)\n'
        '        if problem:\n'
        '            return problem\n'
        '        if (self.control_settings.max_run_time_s > 0 and self.policy_started_at is not None and\n'
        '                monotonic_now-self.policy_started_at >= self.control_settings.max_run_time_s):\n'
        '            return "Run time limit reached; explicit resume required"\n'
        '        start_distance = getattr(self, "_end_straight_start_distance_m", None)\n'
        '        if start_distance is not None:\n'
        '            for name in ("wheel_speed", "imu_angular_velocity"):\n'
        '                observation = self.observations.get(name)\n'
        '                timeout = min(self.sensor_timeout_s[name], self.estimation_settings.max_source_age_s,\n'
        '                              self.estimation_settings.motion_max_gap_s)\n'
        '                if (observation is None\n'
        '                        or self._age(observation, monotonic_now, ros_now_ns) >= timeout):\n'
        '                    return f"End straight required sensor {name} is missing or stale"\n'
        '            if self.distance_limiter.distance_m-start_distance+1e-9 >= self.control_settings.end_straight_distance_m:\n'
        '                return "End straight distance reached; explicit resume required"\n'
        '            if monotonic_now-self._end_straight_started_at_s >= self.control_settings.end_straight_max_time_s:\n'
        '                return "End straight time limit reached; explicit resume required"\n'
        '            return None  # No road reference is consumed in fixed-command mode.\n'
        '        deadline = self.last_control_reference_deadline_s\n'
        '        manager = getattr(self, "control_reference_manager", None)\n'
        '        if (self._robust_control_enabled() and manager is not None\n'
        '                and manager.mode == "DEGRADED"):\n'
        '            problem = manager.problem(monotonic_now, self.distance_limiter.distance_m)\n'
        '            if problem:\n'
        '                return problem + "; explicit resume required"\n'
        '        if deadline is not None and ros_now_ns/1e9 >= deadline:\n'
        '            return "Control reference expired; explicit resume required"\n'
        '        if (not self.control_has_run and self.policy_started_at is not None\n'
        '                and monotonic_now-self.policy_started_at >= self.control_settings.startup_grace_s):\n'
        '            return "Control startup history deadline exceeded; explicit resume required"\n'
        '        return None\n'
        '\n'
        '    def supervision_callback(self):\n'
        '        now, ros_now = self._times()\n'
        '        if self.fsm_state == FSM_STATE_PUBLISHING_POLICY_ACTION:\n'
        '            problem = self._control_health_problem(now, ros_now) or self._control_problem(now, ros_now)\n'
        '            if problem:\n'
        '                self._change_state(FSM_STATE_PUBLISHING_ZERO_ACTIONS, problem)\n'
        '        elif self.fsm_state == FSM_STATE_PUBLISHING_ZERO_ACTIONS:\n'
        '            self.publish_zero_actions()\n'
        '        if now - self._last_status_at >= self.status_period_s:\n'
        '            self.publish_state()\n'
        '\n'
        '    def publish_state(self):\n'
        '        self.state_publisher.publish(Int8(data=self.fsm_state))\n'
        '        self.state_text_publisher.publish(String(data=f"{STATE_NAMES[self.fsm_state]}: {self.state_reason}"))\n'
        '        self._last_status_at = self._monotonic()\n'
        '\n'
        '    def publish_zero_actions(self):\n'
        '        self._publish_actions(0.0, 0.0, None)\n'
        '\n'
        '    def _publish_actions(self, drive, steer, pan):\n'
        '        command = DriveAndSteer()\n'
        '        command.units = DriveAndSteer.UNITS_NORMALIZED\n'
        '        command.drive, command.steer = float(drive), float(steer)\n'
        '        self.action_publisher.publish(command)\n'
        '        if pan is not None:\n'
        '            self.pan_publisher.publish(Float32(data=float(pan)))\n'
        '\n'
        '    def stop_before_shutdown(self):\n'
        '        # Best effort while ROS is still usable. State 1 continues to mean no\n'
        '        # publication; process loss is handled by the independent vehicle node.\n'
        '        if self.fsm_state != FSM_STATE_NOT_PUBLISHING_ACTIONS and self.context.ok():\n'
        '            self.publish_zero_actions()\n'
        '        if getattr(self, "shadow_worker", None) is not None:\n'
        '            self.shadow_worker.close()\n'
        '\n'
        '    def destroy_node(self):\n'
        '        if getattr(self, "shadow_worker", None) is not None:\n'
        '            self.shadow_worker.close()\n'
        '        return super().destroy_node()\n'
        '\n'
        '\n'
        'def main(args=None):\n'
        '    # Keep the context valid until the final zero command has been published.\n'
        "    # ROS's asynchronous signal handler can otherwise invalidate it mid-publish.\n"
        '    rclpy.init(args=args, signal_handler_options=SignalHandlerOptions.NO)\n'
