        '    def request_stop(signum, frame):\n'
        '        raise KeyboardInterrupt\n'
        '\n'
        '    previous_handlers = {sig: signal.signal(sig, request_stop)\n'
        '                         for sig in (signal.SIGINT, signal.SIGTERM)}\n'
        '    node = None\n'
        '    executor = SingleThreadedExecutor()\n'
        '    try:\n'
        '        node = PolicyNode()\n'
        '        executor.add_node(node)\n'
        '        executor.spin()\n'
        '    except (KeyboardInterrupt, ExternalShutdownException):\n'
        '        pass\n'
        '    finally:\n'
        '        if node is not None:\n'
        '            node.stop_before_shutdown()\n'
        '            executor.remove_node(node)\n'
        '            node.destroy_node()\n'
        '        executor.shutdown()\n'
        '        if rclpy.ok():\n'
        '            rclpy.shutdown()\n'
        '        for sig, handler in previous_handlers.items():\n'
        '            signal.signal(sig, handler)\n'
