        'class RoadCenterlinePlanner:\n'
        '    """Pass through the estimator\'s curved centerline with a fixed speed target.\n'
        '\n'
        '    No candidate search, offset recovery trajectory, body model or straight-line\n'
        '    refit. Freshness and geometry encoding are checked synchronously. Forward-\n'
        '    only observations are an explicit MVP option, not a claim of known free\n'
        '    road around the body. This profile has no obstacle avoidance.\n'
        '    """\n'
        '    def __init__(self, settings, frame_id="base_link"):\n'
        '        self.settings, self.frame_id = settings, frame_id\n'
        '        self.sequence = 0\n'
        '\n'
        '    def plan(self, road, state, obstacles, vehicle_limits, now_s,\n'
        '             source_timeout_s=None, mvp=False):\n'
        '        self.sequence += 1\n'
        '        cfg = self.settings\n'
        '        ref = {"schema_version": "planning_reference_v1", "planner_version": "road_centerline",\n'
        '               "trajectory_id": self.sequence, "timestamp_s": now_s,\n'
        '               "frame_id": self.frame_id, "vehicle_reference_point": "cg_ground_projection",\n'
        '               "valid": False, "status": "INVALID_INPUT", "reason": None,\n'
        '               "valid_for_s": 0.0, "path": None, "target_speed_mps": 0.0,\n'
        '               "stop_requested": True, "stop_reason": None, "simulation_only": False}\n'
        '        diag = {"candidate_search_enabled": False, "footprint_check_enabled": False,\n'
        '                "obstacle_response_enabled": False, "forward_only": False}\n'
        '\n'
        '        def fail(reason):\n'
        '            ref.update(reason=reason, stop_reason=reason)\n'
        '            diag["reason"] = reason\n'
        '            return ref, diag\n'
        '\n'
        '        if not mvp:\n'
        '            return fail("road_centerline_requires_mvp")\n'
        '        if not finite_number(now_s) or not isinstance(road, dict) or not isinstance(state, dict):\n'
        '            return fail("invalid_centerline_input")\n'
        '        if not road.get("valid"):\n'
        '            forward = road.get("forward_geometry")\n'
        '            if (cfg.allow_forward_only\n'
        '                    and (road.get("status") == "near_field_unobserved"\n'
        '                         or (road.get("status") == "near_field_requires_both_boundaries"\n'
        '                             and isinstance(forward, dict)\n'
        '                             and forward.get("single_side_inferred_from_learned_width") is True))\n'
        '                    and isinstance(forward, dict) and forward.get("geometry_valid") is True\n'
        '                    and forward.get("time_aligned") is True):\n'
        '                road = forward  # Keep the estimator output intact; no extension.\n'
        '                diag["forward_only"] = True\n'
        '            else:\n'
        '                return fail("invalid_road_"+str(road.get("status")))\n'
