        '            path.update(type="ORDERED_CENTERLINE", independent_variable="s_m",\n'
        '                        range=[0.0, lengths[-1]])\n'
        '        # Explicit constant-speed policy, including valid predicted roads.\n'
        '        # Do not consume their speed advisory; retain original prediction expiry.\n'
        '        ref.update(valid=True, status="TRACK", reason="road_centerline_available",\n'
        '                   valid_for_s=min(deadlines), path=path, target_speed_mps=cfg.cruise_speed_mps,\n'
        '                   stop_requested=False, stop_reason=None, operating_profile="mvp_centerline_follow")\n'
        '        diag.update(reason=ref["reason"], point_count=len(points),\n'
        '                    x_range_m=[min(p[0] for p in points), max(p[0] for p in points)],\n'
        '                    path_encoding=path["type"], path_length_m=path["range"][1] if ordered else None,\n'
        '                    inferred_single_side=inferred_single_side,\n'
        '                    boundary_visibility=road.get("visibility"),\n'
        '                    centerline_source=road.get("centerline_source", "two_boundaries"),\n'
        '                    lane_width_m=road.get("lane_width_m"),\n'
        '                    inward_offset_m=road.get("inward_offset_m"),\n'
        '                    lane_width_observed_at_s=road.get("lane_width_observed_at_s"),\n'
        '                    road_degraded=bool(road.get("degraded")), speed_policy="constant",\n'
        '                    target_speed_mps=cfg.cruise_speed_mps,\n'
        '                    reference_timestamp_s=ref["timestamp_s"], reference_valid_for_s=ref["valid_for_s"],\n'
        '                    source_measurement_timestamp_s=road.get("measurement_timestamp_s"),\n'
        '                    recommended_speed_scale=road.get("recommended_speed_scale"))\n'
        '        return ref, diag\n'
